pdd_component_mapping = {
     "TRSW": ["SE_FTM_pdd"],
     }

pdd_paths = {
    "SE_FTM_pdd": "trs/test_autom/pdd/"
}


def get_path_to_component_pdds(component_name):
    component_pdds = pdd_component_mapping[component_name]
    component_pdd_map = {}
    for pdd in component_pdds:
        component_pdd_map[pdd+".yaml"] = pdd_paths[pdd]
    return component_pdd_map
